import json,pathlib
r=pathlib.Path(__file__).resolve().parent.parent;jobs=json.loads((r/'design/creatures/generation-jobs.json').read_text()); entries=[]
for j in jobs:
 d=r/j['directory']
 if not (d/'frames.json').exists():continue
 entries.append(dict(name=j['name'],category=j['category'],directory=j['directory'],meta=json.loads((d/'frames.json').read_text()),poses=j['poses']))
for name in ['dragon','mountain','kitsune']:
 d='design/creatures/'+name; m=json.loads((r/d/'frames.json').read_text());entries.append(dict(name=name,category='approved identity',directory=d,meta=m,poses=['Approved pose '+str(i+1) for i in range(4)]))
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Frostline · creature art handoff</title><style>*{box-sizing:border-box}body{font:16px system-ui;background:#18333f;color:#f3ead5;margin:24px}a{color:#e4bd6f}header{max-width:900px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:18px}article{overflow:auto;padding:16px;border:1px solid #73938f;border-radius:8px}h2{margin:0 0 8px;text-transform:capitalize}canvas,img{image-rendering:pixelated}canvas{background:#edf1df;max-width:none}select{max-width:100%;padding:6px}p{line-height:1.5}.links{font-size:13px}button{padding:7px;margin:0 6px}#zoom{position:sticky;top:8px;z-index:2;background:#18333f;padding:10px;width:fit-content}</style><header><h1>Frostline creature art</h1><p>Native-size art beside the actual 22-pixel skier. Select each pose to inspect it; 3× zoom enlarges pixels without smoothing. These are art deliverables, not newly enabled game mechanics. Dragon, Stone Ram and Kitsune retain their approved identities.</p><p><a href="design/creatures/README.md">Implementation handoff</a> · <a href="design/CREATURES.md">Creature design guide</a> · <a href="index.html">Play Frostline</a></p></header><div id="zoom"><button data-zoom="1">Native 1×</button><button data-zoom="3">Pixel zoom 3×</button></div><main></main><script>const entries=__DATA__;let zoom=1;const atlas=new Image();atlas.src='assets/gritty-sprites.png';const loads=[];for(const e of entries){const card=document.createElement('article');card.innerHTML='<h2>'+e.name+'</h2><div class="links">'+e.category+' · <a href="'+e.directory+'/source.png">Source</a> · <a href="'+e.directory+'/native.png">Native sheet</a> · <a href="'+e.directory+'/frames.json">Frames</a> · <a href="'+e.directory+'/prompt.txt">Prompt</a></div><p><select aria-label="'+e.name+' pose"></select></p><canvas></canvas>';document.querySelector('main').append(card);const select=card.querySelector('select'),c=card.querySelector('canvas');for(const [i,f]of (e.meta.frames||[]).entries())select.add(new Option(f.name||e.poses[i],i));const im=new Image();im.src=e.directory+'/native.png';e.draw=()=>{const frames=e.meta.frames||[],f=frames[+select.value]||{x:0,y:0,w:320,h:200};const w=Math.max(320,f.w+80),h=Math.max(150,f.h+28);c.width=w*zoom;c.height=h*zoom;const t=c.getContext('2d');t.imageSmoothingEnabled=false;t.scale(zoom,zoom);t.fillStyle='#edf1df';t.fillRect(0,0,w,h);t.fillStyle='#a6bec5';t.fillRect(0,h-22,w,1);t.drawImage(im,f.x,f.y,f.w,f.h,30,h-30-f.h,f.w,f.h);if(e.category!=='scene')t.drawImage(atlas,512,0,22,24,Math.min(w-36,f.w+55),h-54,22,24);};select.onchange=e.draw;loads.push(im.decode());}Promise.all([...loads,atlas.decode()]).then(()=>entries.forEach(e=>e.draw()));document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{zoom=+b.dataset.zoom;entries.forEach(e=>e.draw())});</script>'''.replace('__DATA__',json.dumps(entries))
(r/'creature-art.html').write_text(html)
